#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace Veilbound.Editor {
 public static class VeilAtmosphereSetup {
  const string Output="VeilAtmosphereUpdate";
  [Serializable]class Result{public bool passed;public int graveyardEmbers,villageEmbers;public float meanMistChange,maxMistChange,meanEmberChange;public bool stableMesh,finiteParticles;}
  static void Need(bool ok,string message){if(!ok)throw new Exception("Veil atmosphere: "+message);}
  public static void Build(){Run();ProductionModelImport.Build();}
  public static void Run(){
   Directory.CreateDirectory(Output);AssetDatabase.Refresh();var shader=Shader.Find("Veilbound/AmbientEmbers");Need(shader&&shader.isSupported,"ember shader compiles");const string asset="Assets/Veilbound/Resources/VeilAmbientEmbers.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(asset);if(!material){material=new Material(shader){name="Veil ambient embers - subtle"};AssetDatabase.CreateAsset(material,asset);}material.SetColor("_Color",new Color(1,.38f,.10f,.85f));EditorUtility.SetDirty(material);AssetDatabase.SaveAssets();
   EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=WorldArt.Group("Veil atmosphere preview");var collision=new ArenaCollision();GraveyardArena.Build(root,collision);var veil=new VeilBoundary(root,collision.PlayerRadius);var result=new Result{graveyardEmbers=veil.Ambient.Count};int meshId=veil.Ambient.Mesh.GetInstanceID();veil.Tick(4);Need(veil.Ambient.Mesh.GetInstanceID()==meshId,"particle mesh reused while drifting");result.stableMesh=true;result.finiteParticles=veil.Ambient.Mesh.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)&&v.y>=.25f&&v.y<2.76f);Need(result.finiteParticles,"particles remain low and finite");
   RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.36f,.35f,.32f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.075f,.083f,.075f);RenderSettings.fogStartDistance=35;RenderSettings.fogEndDistance=85;var sun=new GameObject("Scene key").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.05f;sun.color=new Color(.98f,.94f,.86f);sun.transform.rotation=Quaternion.Euler(45,-35,0);
   var camera=new GameObject("Atmosphere preview camera").AddComponent<Camera>();camera.enabled=false;camera.orthographic=true;camera.orthographicSize=12;camera.aspect=1.6f;camera.nearClipPlane=.1f;camera.farClipPlane=160;camera.transform.position=new Vector3(7,15,-16);camera.transform.LookAt(Vector3.up*.5f);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=RenderSettings.fogColor;var fog=camera.gameObject.AddComponent<VeilFogEffect>();fog.ConfigureBounds(collision);var embers=veil.Ambient.GetComponent<MeshRenderer>();
   fog.interiorMistDensity=0;embers.enabled=false;var baseline=Capture(camera,"01-baseline.png");fog.interiorMistDensity=.28f;var mist=Capture(camera,"02-light-mist.png");float total=0,maximum=0;for(int i=0;i<baseline.Length;i++){float delta=(Mathf.Abs(mist[i].r-baseline[i].r)+Mathf.Abs(mist[i].g-baseline[i].g)+Mathf.Abs(mist[i].b-baseline[i].b))/3;total+=delta;maximum=Mathf.Max(maximum,delta);}result.meanMistChange=total/baseline.Length;result.maxMistChange=maximum;Need(result.meanMistChange>.01f&&result.meanMistChange<.12f&&maximum<.30f,"light mist is visible without a heavy screen wash");
   embers.enabled=true;var complete=Capture(camera,"03-mist-and-embers.png");total=0;for(int i=0;i<complete.Length;i++)total+=(Mathf.Abs(complete[i].r-mist[i].r)+Mathf.Abs(complete[i].g-mist[i].g)+Mathf.Abs(complete[i].b-mist[i].b))/3;result.meanEmberChange=total/complete.Length;Need(result.meanEmberChange>0&&result.meanEmberChange<.001f,"embers appear sparsely in the rendered scene");
   var village=new GameObject("Village ambient count QA");var effect=village.AddComponent<VeilAmbientEmbers>();effect.Initialize(52.5f);result.villageEmbers=effect.Count;Need(result.graveyardEmbers==192&&result.villageEmbers==300,"density follows map size with a fixed budget");UnityEngine.Object.DestroyImmediate(village);result.passed=true;File.WriteAllText(Output+"/validation.json",JsonUtility.ToJson(result,true));Debug.Log("VEILBOUND_ATMOSPHERE_SETUP_PASS "+JsonUtility.ToJson(result));
  }
  static Color[] Capture(Camera camera,string name){var rt=new RenderTexture(1600,1000,24);camera.targetTexture=rt;camera.Render();var prior=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1000),0,0);image.Apply();File.WriteAllBytes(Output+"/"+name,image.EncodeToPNG());var pixels=image.GetPixels();RenderTexture.active=prior;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);return pixels;}
 }
}
#endif
